M7_DECKS.push({ id: 'm7-nm', fa: 'fa1', title: 'Naming organic compounds', dps: ['7.1.1'], cards: [
  { id: 'onm01', dp: '7.1.1', t: 'def', q: 'What is an organic compound, and who sets the rules for naming them?',
    a: L(['A compound containing at least one <b>carbon–hydrogen bond</b>; the carbons are usually arranged in chains or rings.', 'Naming rules are set by <b>IUPAC</b>. Each compound has a preferred IUPAC name (PIN), usually the systematic name but sometimes a common name (e.g. water, ammonia, acetic acid).']) + N('In the HSC, read the question carefully to see whether a systematic or common name is required.') },
  { id: 'onm02', dp: '7.1.1', t: 'rec', q: 'Give the stems used for carbon chains of 1 to 8 carbons.',
    a: L(['1 meth-, 2 eth-, 3 prop-, 4 but-', '5 pent-, 6 hex-, 7 hept-, 8 oct-', '(9 non-, 10 dec-)']) },
  { id: 'onm03', dp: '7.1.1', t: 'def', q: 'What name endings show single, double and triple carbon–carbon bonds?',
    a: L(['<b>Alkanes</b>, only C–C single bonds: <b>-ane</b> (e.g. propane, hexane)', '<b>Alkenes</b>, a C=C double bond: <b>-ene</b> (e.g. prop-1-ene)', '<b>Alkynes</b>, a C≡C triple bond: <b>-yne</b> (e.g. ethyne)']) },
  { id: 'onm04', dp: '7.1.1', t: 'con', q: 'What is a locant, and how do you choose its number for a double or triple bond?',
    a: L(['A locant gives the position of the bond; it’s needed for chains of 3 or more carbons.', 'Number the chain from the end that gives the bond the <b>lowest</b> number; the locant is the first carbon of the bond.', 'It goes just before the part it locates, with a dash between numbers and letters.', 'E.g. numbering one way gives 4, the other gives 2, so the name is <b>hex-2-ene</b>.']) + N('Butene has only two isomers by position, but-1-ene and but-2-ene: ‘but-3-ene’ is just but-1-ene numbered from the other end.') },
  { id: 'onm05', dp: '7.1.1', t: 'con', q: 'How do you name a chain with several double (or triple) bonds?',
    a: L(['Add an ‘a’ to the stem (propa-, buta-, octa-).', 'Use a prefix for how many: di, tri, tetra…', 'Give the first bond the lowest locant; if tied, go to the first point of difference.', 'Separate locants with commas.']) + P('Example: <b>octa-1,2,5,7-tetraene</b>.') },
  { id: 'onm06', dp: '7.1.1', t: 'con', q: 'How do you name a chain that has both a double and a triple bond?',
    a: L(['Number to give the lowest locant to whichever multiple bond comes first; if both directions tie, the <b>double bond</b> gets the lower number.', 'Write ‘-en-’ before ‘-yne’, dropping the ‘e’ of ‘ene’ (vowel rule).']) + P('Examples: <b>pent-1-en-3-yne</b>; <b>but-1-en-3-yne</b>.') },
  { id: 'onm07', dp: '7.1.1', t: 'calc', q: 'Name: (a) CH_2=CHCH=CHCH=CH_2 (b) CH_2=CHCH=CHCH_3 (c) CH_2=CHCH_2CH_2C≡CCH_3',
    a: L(['(a) <b>hexa-1,3,5-triene</b>', '(b) <b>penta-1,3-diene</b>', '(c) <b>hept-1-en-5-yne</b>']) },
  { id: 'onm08', dp: '7.1.1', t: 'def', q: 'How are halogen substituents named and numbered?',
    a: L(['F, Cl, Br, I become <b>fluoro, chloro, bromo, iodo</b>, added to the start of the name.', 'A locant is needed for 3 or more carbons, or when there are several substituents.', 'Several of the same halogen take di, tri… prefixes.', 'Give the lowest first locant; if tied, go to the first point of difference: <b>1,1,3-trifluoropropane</b>, not 1,3,3-.', 'A double/triple bond or functional group takes priority for the lowest locant.']) },
  { id: 'onm09', dp: '7.1.1', t: 'con', q: 'How do you order and number several different halogens?',
    a: L(['Treat them all equally for numbering: lowest locant at the first point of difference.', 'If still tied, the halogen first in the alphabet gets the lower number.', 'Write them in <b>alphabetical order</b> of the halogen name (ignore di/tri), not in locant order.']) + P('Examples: <b>1,1-dibromo-2,3-difluoropropane</b>; <b>4-bromo-1,3,3-trichloro-1,1-difluorobutane</b>.') },
  { id: 'onm10', dp: '7.1.1', t: 'def', q: 'How are alkyl side chains handled when naming?',
    a: L(['The <b>parent chain</b> is the longest continuous carbon chain, and it must include any double/triple bond or functional group.', 'Side chains are named by their carbons: <b>methyl</b> (1 C), <b>ethyl</b> (2 C).', 'They’re treated exactly like halogens for placement and locants.', 'HSC side chains are always simple C–C chains with only hydrogens.']) + P('Examples: 2-methylpentane; 2,3,4-trimethylpentane; 4-ethyl-2-methylhexane.') },
  { id: 'onm11', dp: '7.1.1', t: 'calc', q: 'Name: (a) CH_3CH_2CH(CH_3)CH_2CH_3 (b) CH_3CBr_2CH_2C(CH_3)_2CH_2CH_3',
    a: L(['(a) <b>3-methylpentane</b>', '(b) 6-carbon chain; numbering from the left gives 2,2,4,4 (right gives 3,3,5,5); halogens and alkyls are equal and alphabetical: <b>2,2-dibromo-4,4-dimethylhexane</b>']) },
  { id: 'onm12', dp: '7.1.1', t: 'calc', q: 'Name: (a) CH_2=CHCH_2CH(CH_3)CH_3 (b) CH_2=CHCBr_2CH_2Br',
    a: P('The double bond gets the lowest locant before substituents.') + L(['(a) <b>4-methylpent-1-ene</b>', '(b) <b>3,3,4-tribromobut-1-ene</b>']) },
  { id: 'onm13', dp: '7.1.1', t: 'def', q: 'What are functional groups, and how do they affect a name?',
    a: L(['Parts of an organic molecule that particularly affect its chemical and physical properties. The HSC ones all contain oxygen, nitrogen or both.', 'They change the <b>suffix</b> (end of the name).', 'You’ll only name one type of functional group at a time.', 'The functional group always has priority for the lowest locant.']), v: 'img:m7_fgroups' },
  { id: 'onm14', dp: '7.1.1', t: 'def', q: 'How are alcohols named? Name CH_3CH(OH)CH_2CH_2OH.',
    a: L(['Hydroxyl group (–OH) → suffix <b>-ol</b>; the ‘e’ of -ane drops before a vowel: methan<b>ol</b>, not methaneol.', 'Locant needed for 3 or more carbons, placed just before -ol.', 'Two or three –OH: -diol, -triol, and the ‘e’ stays (butane-1,3-diol).']) + P('Numbering from the right gives 1,3: <b>butane-1,3-diol</b>. Others: hexan-3-ol, pentane-1,3-diol.') },
  { id: 'onm15', dp: '7.1.1', t: 'def', q: 'How are aldehydes named?',
    a: L(['Carbonyl group (C=O) on a <b>terminal</b> carbon → suffix <b>-al</b>.', 'Always at a chain end, so no locant; at most two (-dial, keeping the ‘e’).']) + P('Examples: ethanal, propanal, butanedial, pentanedial.') },
  { id: 'onm16', dp: '7.1.1', t: 'def', q: 'How are ketones named?',
    a: L(['Carbonyl group on a <b>non-terminal</b> carbon → suffix <b>-one</b>.', 'Always 3+ carbons, so always needs a locant, placed just before -one.', 'Several: -dione, -trione.']) + P('Examples: propan-2-one, pentan-2-one, hexane-2,4-dione, heptane-2,4,5-trione.') },
  { id: 'onm17', dp: '7.1.1', t: 'def', q: 'How are carboxylic acids named?',
    a: L(['A carbonyl and a hydroxyl on the same carbon (–COOH) → suffix <b>-oic acid</b>.', 'This uses 3 of the carbon’s 4 bonds, so it’s always terminal: no locant, at most two (-dioic acid).']) + P('Examples: ethanoic acid, butanoic acid, pentanedioic acid, heptanedioic acid.') },
  { id: 'onm18', dp: '7.1.1', t: 'def', q: 'How are amines named, including chains on the nitrogen?',
    a: L(['N bonded to a carbon of the parent chain → suffix <b>-amine</b>; locant for 3+ carbons, placed before -amine; several: -diamine.', 'The <b>longest</b> carbon chain is the parent; other chains on the N are substituents with locant <b>N</b>.']) + P('Examples: ethanamine, butan-2-amine, pentane-1,4-diamine, N-ethylpropan-1-amine, N,N-dimethylpentan-3-amine.') },
  { id: 'onm19', dp: '7.1.1', t: 'def', q: 'How are amides named, and how is their parent chain chosen?',
    a: L(['An amine N plus a carbonyl on the same carbon (–CONH_2) → suffix <b>-amide</b>; always terminal, so no locant; two: -diamide.', 'Chains on the N get the locant N.', 'Unlike amines, the parent chain is the one containing the <b>C=O</b>, not the longest.']) + P('Examples: propanamide, butanediamide, N-ethylethanamide, N-ethyl-N-methylmethanamide.') },
  { id: 'onm20', dp: '7.1.1', t: 'def', q: 'How are esters named? Name CH_3COOCH_3.',
    a: L(['Formed when an alcohol bonds with a carboxylic acid.', 'The chain with the carbonyl directly attached is the parent → <b>-oate</b>.', 'The chain singly bonded to the O is a substituent: a separate word first, no locant. General name: <b>alkyl alkanoate</b>.']) + P('CH_3COOCH_3 is <b>methyl ethanoate</b>.') },
  { id: 'onm21', dp: '7.1.1', t: 'def', q: 'How are cyclic compounds named?',
    a: L(['Put <b>cyclo-</b> before the stem.', 'Alkanes, alkenes, alkynes and any non-terminal functional group can be present.', 'Still number to give the priority group the lowest locant.']) + P('Examples: cycloheptane; 3-bromocyclopentan-1-ol.') },
  { id: 'onm22', dp: '7.1.1', t: 'rec', q: 'What limits does the HSC set on the compounds you can be asked to name?',
    a: L(['Parent chain no longer than 8 carbons', 'Only one type of functional group (but possibly several of it)', 'Double and triple bonds can be in the parent chain', 'Substituents can be included', 'Side chains are simple hydrocarbon chains with no double or triple bonds']) },
  { id: 'onm23', dp: '7.1.1', t: 'con', q: 'In what order do you build a systematic name, and what decides the locants?',
    a: OL(['Functional group → the <b>ending</b>', 'Chain length and bond type → the <b>stem</b> (general formulae: alkane C_{n}H_{2n+2}, alkene C_{n}H_{2n}, alkyne C_{n}H_{2n−2})', 'Substituents (halogens, alkyl side chains) → the <b>start</b>, alphabetical']) + P('Locant priority: functional group first, then double/triple bonds, then substituents.') },
  { id: 'onm24', dp: '7.1.1', t: 'calc', q: 'Name: (a) CH_3COCH_2CH=CHCH=CH_2 (b) CH_3CCl(OH)CH(OH)CH(CH_3)CH_3',
    a: L(['(a) Ketone gets priority (2 from the left), then double bonds at 4 and 6: <b>hepta-4,6-dien-2-one</b>', '(b) Two –OH at 2 and 3, chloro at 2, methyl at 4: <b>2-chloro-4-methylpentane-2,3-diol</b>']) },
  { id: 'onm25', dp: '7.1.1', t: 'calc', q: 'Name: (a) CHF_2CHBrCH(OH)CH_3 (b) CH_3CH_2COOCH_2CH_2CH_2CH_3',
    a: L(['(a) <b>3-bromo-4,4-difluorobutan-2-ol</b>', '(b) <b>butyl propanoate</b>']) },
  { id: 'onm26', dp: '7.1.1', t: 'rec', q: 'Give the common names of methanal, propanone, ethanoic acid and 3-methylbutyl ethanoate.',
    a: L(['methanal: <b>formaldehyde</b>', 'propan-2-one: <b>acetone</b>', 'ethanoic acid: <b>acetic acid</b> (vinegar, CH_3COOH)', '3-methylbutyl ethanoate: <b>isoamyl acetate</b>']) }
]});

M7_DECKS.push({ id: 'm7-rp', fa: 'fa1', title: 'Representing molecules and isomers', dps: ['7.1.1', '7.1.2'], cards: [
  { id: 'orp01', dp: '7.1.1', t: 'def', q: 'What does a structural formula show, and when must you show every bond?',
    a: L(['Every atom, including hydrogens, and every bond individually, in 2D: enough to name the compound.', 'Bonds inside polyatomic groups (–OH, –NH_2) aren’t always drawn.', 'When relating structure to physical properties, show all bonds. When in doubt, show all bonds.']) },
  { id: 'orp02', dp: '7.1.1', t: 'def', q: 'What are the rules for reading a skeletal formula?',
    a: L(['Carbons and hydrogens are inferred; all other atoms are shown.', 'A corner with no symbol is a carbon.', 'The end of a double or triple bond is a carbon, even with no bend.', 'Carbon always forms four bonds, so a terminal carbon has 3 hydrogens.']) },
  { id: 'orp03', dp: '7.1.1', t: 'def', q: 'What is a condensed structural formula? Give the rules for writing one.',
    a: L(['Also called semi-structural: shows how atoms connect along the carbon backbone, e.g. 2-bromopropane is CH_3CHBrCH_3.', 'Draw the full structural formula first.', 'Write the longest chain first, with functional groups towards the end.', 'Put side chains in brackets after the carbon they’re attached to.', 'Write aldehydes as CHO (not COH) so they aren’t confused with an alcohol.']) + P('E.g. butanal is CH_3CH_2CH_2CHO.') },
  { id: 'orp04', dp: '7.1.1', t: 'def', q: 'What is a homologous series, and what does a general structural formula show?',
    a: L(['A homologous series is a group of organic compounds with the <b>same functional group</b> and similar chemical properties (e.g. the alcohols).', 'A general structural formula uses <b>R</b> for the rest of the molecule, e.g. R–X for haloalkanes, R–OH for alcohols.', 'Molecular and empirical formulae are also used: 2-bromopropane is C_3H_7Br for both.']) },
  { id: 'orp05', dp: '7.1.2', t: 'def', q: 'What are isomers? Name the three main categories.',
    a: P('Compounds with the <b>same molecular formula</b> but different structural formulae.') + L(['<b>Structural</b>: different organisation of atoms and bonds (e.g. propan-1-ol and propan-2-ol). The only type in the HSC.', '<b>Geometrical</b>: same bonding, different arrangement in space (cis- and trans-but-2-ene).', '<b>Configurational/optical</b>: same bonding, arranged as non-superimposable mirror images.']) },
  { id: 'orp06', dp: '7.1.2', t: 'def', q: 'Name and describe the three types of structural isomer, with examples.',
    a: L(['<b>Chain</b>: the carbon chain arrangement differs, e.g. hexane, 2-methylpentane, 3-methylpentane.', '<b>Position</b>: same functional group in a different position, e.g. but-1-yne and but-2-yne.', '<b>Functional group</b>: different functional groups, e.g. propanal and propanone (aldehydes/ketones; also carboxylic acids/esters).']) },
  { id: 'orp07', dp: '7.1.2', t: 'con', q: 'Classify each pair: (a) propan-1-ol and propan-2-ol (b) propanal and propanone (c) hexane and 2-methylpentane',
    a: L(['(a) <b>position</b> isomers', '(b) <b>functional group</b> isomers', '(c) <b>chain</b> isomers']) },
  { id: 'orp08', dp: '7.1.1', t: 'con', q: 'Why is ‘N-ethylpropanamine’ not a valid name?',
    a: P('The amine needs a locant because propane has 3 carbons. It should be <b>N-ethylpropan-1-amine</b>.') },
  { id: 'orp09', dp: '7.1.2', t: 'rec', q: 'What is the smallest stable carbon ring?',
    a: P('Three- or four-carbon rings are inherently unstable; the smallest stable ring has <b>five</b> carbons.') }
]});

M7_DECKS.push({ id: 'm7-hc', fa: 'fa2', title: 'Hydrocarbons: structure, shape and properties', dps: ['7.2.1', '7.2.2', '7.2.3', '7.2.4'], cards: [
  { id: 'ohc01', dp: '7.2.1', t: 'def', q: 'What are aliphatic and aromatic hydrocarbons?',
    a: L(['<b>Aliphatic</b>: the alkane, alkene and alkyne homologous series.', '<b>Aromatic</b>: contain at least one benzene ring, which changes their properties substantially. Aromatic chemistry is outside the HSC course.']) },
  { id: 'ohc02', dp: '7.2.1', t: 'rec', q: 'What are the general formulae of alkanes, alkenes and alkynes? What are the common names (PINs) of ethene and ethyne?',
    a: L(['Alkanes C_{n}H_{2n+2}; alkenes C_{n}H_{2n}; alkynes C_{n}H_{2n−2}', 'Ethene = <b>ethylene</b>; ethyne = <b>acetylene</b>. Know both names.']) },
  { id: 'ohc03', dp: '7.2.1', t: 'calc', q: 'Name each and identify its functional group: (a) (CH_3)_2C=C(CH_3)_2 (b) CH≡CCH(CH_3)CH_3 (c) CH_3CH_2CH(CH_3)CH_2CH_2CH_3',
    a: L(['(a) <b>2,3-dimethylbut-2-ene</b>: double bond', '(b) <b>3-methylbut-1-yne</b>: triple bond', '(c) <b>3-methylhexane</b>: no functional group']) },
  { id: 'ohc04', dp: '7.2.3', t: 'con', q: 'What does VSEPR theory say, and how does it apply to carbon?',
    a: L(['Valence electron pairs around an atom arrange themselves as far apart as possible, which sets the shape.', 'Carbon forms four covalent bonds; how its four shared pairs spread out sets the shape and bond angles.', 'E.g. methane is tetrahedral, 109.5°.']) },
  { id: 'ohc05', dp: '7.2.3', t: 'con', q: 'Compare the shape around carbon in alkanes, alkenes and alkynes.',
    a: L(['<b>Alkane</b> (single bonds): 4 electron domains, <b>tetrahedral, 109.5°</b>; free rotation around bonds.', '<b>Alkene</b> (C=C): 3 domains, <b>trigonal planar, 120°</b>; the double bond doesn’t allow free rotation.', '<b>Alkyne</b> (C≡C): 2 domains, <b>linear, 180°</b>.']), v: 'img:m7_shapes' },
  { id: 'ohc06', dp: '7.2.3', t: 'con', q: 'Why are double and triple C–C bonds more reactive, not ‘stronger’? (sigma and pi bonds)',
    a: L(['<b>Sigma (σ)</b> bonds: direct head-on orbital overlap; strong. All single bonds are sigma bonds.', '<b>Pi (π)</b> bonds: side-by-side overlap of p orbitals; weaker. Only in double and triple bonds.', 'So double and triple bonds are more susceptible to chemical attack.']) },
  { id: 'ohc07', dp: '7.2.4', t: 'rec', q: 'Describe the three types of intermolecular force and their relative strength.',
    a: L(['<b>Dispersion</b>: temporary dipoles; in all molecules; larger molecules (more electrons) = stronger. Strength 0.1–1.', '<b>Dipole–dipole</b>: permanent dipoles in polar molecules (polar bonds + asymmetry). Strength 1–3.', '<b>Hydrogen bonding</b>: H bonded to O, N or F attracted to a lone pair on another O, N or F. Strength about 10.']) + N('Strengths are relative to a covalent bond set at 100.') },
  { id: 'ohc08', dp: '7.2.4', t: 'con', q: 'Why are alkanes non-polar, and which intermolecular force do they have?',
    a: L(['Each carbon bonds to four atoms, so alkanes are <b>saturated</b>, held together by covalent bonds.', 'C and H have similar electronegativity, so all bonds are non-polar and the molecules are non-polar.', 'So only <b>dispersion forces</b> act between alkane molecules.']) },
  { id: 'ohc09', dp: '7.2.4', t: 'con', q: 'What general physical properties do alkanes have, and why?',
    a: P('Only weak dispersion forces, so:') + L(['low melting and boiling points', 'volatile', 'low hardness and low density', 'poor solubility in water', 'poor electrical conductivity (no free charges in covalent substances)']) },
  { id: 'ohc10', dp: '7.2.4', t: 'con', q: 'How do alkane properties change as chain length increases?',
    a: P('Larger molecules have more electrons, so stronger dispersion forces:') + L(['melting and boiling points increase', 'volatility decreases', 'hardness and density increase']) + P('Boiling points: methane −161.5 °C, ethane −88.6 °C, propane −42.1 °C, butane −0.5 °C.') },
  { id: 'ohc11', dp: '7.2.4', t: 'con', q: 'Why does a branched alkane boil at a lower temperature than a straight-chain isomer?',
    a: P('Branching makes the molecule more compact, reducing surface area and preventing close packing. Dispersion forces are weaker, so melting and boiling points are slightly lower than for a linear alkane of the same molar mass.') },
  { id: 'ohc12', dp: '7.2.4', t: 'con', q: 'Why are alkanes insoluble in water?',
    a: P('A substance dissolves if its intermolecular forces are similar to the solvent’s (‘like dissolves like’). Water is polar with hydrogen bonding; alkanes are non-polar, so they can’t form strong attractions with water molecules.') },
  { id: 'ohc13', dp: '7.2.2', t: 'prac', q: 'Prac 7.1: Describe and explain the trend in water solubility of the alcohols.',
    a: P('Solubility at 20 °C: methanol, ethanol and propan-1-ol mix completely; butanol 77 g/L; pentanol 22; hexanol 5.9; heptanol 1.0; octanol 0.0.') + P('As the chain gets longer, the non-polar ‘hydrophobic’ part grows and interferes with water, so the alcohol can’t form enough hydrogen bonds to dissolve.') },
  { id: 'ohc14', dp: '7.2.1', t: 'rec', q: 'What state are alkanes, alkenes and alkynes at room temperature?',
    a: L(['4 or fewer backbone carbons: <b>gases</b>', 'Between 5 and about 15 carbons: <b>liquids</b>']) }
]});

M7_DECKS.push({ id: 'm7-sf', fa: 'fa2', title: 'Safety and implications of hydrocarbons', dps: ['7.2.5', '7.2.6'], cards: [
  { id: 'osf01', dp: '7.2.5', t: 'con', q: 'What hazards do organic compounds pose?',
    a: L(['Irritants (skin, eyes, respiratory surfaces)', 'Toxic, by skin contact and/or inhalation', 'Corrosive', 'Immiscible with water', 'Carcinogenic, usually after long-term exposure', 'Most are <b>highly flammable</b>']) },
  { id: 'osf02', dp: '7.2.5', t: 'def', q: 'Define flash point and ignition temperature.',
    a: L(['<b>Flash point</b>: the minimum temperature at which a liquid gives off enough vapour to form an ignitable mixture with air.', '<b>Ignition temperature</b>: the minimum temperature needed to start self-sustained combustion without a heat source.']) },
  { id: 'osf03', dp: '7.2.5', t: 'con', q: 'In what order should risk minimisations be developed? What is an SDS?',
    a: OL(['<b>Avoidance</b>: is the material or experiment needed; is there an alternative?', '<b>Safe handling</b>: minimal quantities, dispensing equipment, no flames or sparks, fume hood, ventilation, waste disposal.', '<b>PPE</b>: safety glasses, enclosed leather shoes, gloves.', '<b>Spill/accident protocols</b>.']) + P('A Safety Data Sheet (SDS) is legally required for every material. It summarises health and safety information and how to handle, store and use it safely.') },
  { id: 'osf04', dp: '7.2.5', t: 'con', q: 'Using cyclohexane’s properties, justify the safety precautions it needs.',
    a: L(['Low boiling point → high volatility → good ventilation', 'High vapour production → inhalation hazard → PPE', 'Weak intermolecular forces → highly flammable → strict ignition control', 'Low polarity → poor miscibility with water → spills spread over surfaces']) },
  { id: 'osf05', dp: '7.2.5', t: 'prac', q: 'Prac 7.2: What safety measures are used when reacting hydrocarbons with bromine water?',
    a: L(['Nitrile gloves, enclosed shoes, safety glasses; eliminate ignition sources', 'Dispense chemicals in the fume hood; ensure ventilation', 'Collect organic waste; never pour it down the sink', 'Manage spills immediately; for skin or eye contact, rinse with copious water']) },
  { id: 'osf06', dp: '7.2.6', t: 'con', q: 'Outline key implications of obtaining and using hydrocarbons.',
    a: L(['Hydrocarbons come mainly from crude oil or natural gas, which is mined and split into components by fractional distillation.', 'Mining and transport can have major environmental, economic and sociocultural impacts when accidents occur.', 'CO_2 from combustion is a significant contributor to the enhanced greenhouse effect (climate, sea levels, sea ice, severe weather) and to ocean acidity.', 'Polymers made from hydrocarbons cause pollution and waste.']) }
]});

M7_DECKS.push({ id: 'm7-rx', fa: 'fa3', title: 'Reactions of hydrocarbons', dps: ['7.3.1', '7.3.2'], cards: [
  { id: 'orx01', dp: '7.3.1', t: 'con', q: 'Why do unsaturated hydrocarbons undergo addition reactions?',
    a: L(['Double and triple bonds are regions of high electron density.', 'Electrophiles (e.g. halogens) are attracted and break the weaker pi bond.', 'Only the sigma bond is left joining the carbons, giving a saturated molecule.', 'The reagent ‘adds across’ the carbons either side of the multiple bond.']) },
  { id: 'orx02', dp: '7.3.1', t: 'rec', q: 'Name the addition reactions of ethylene with H_2, X_2, HX and H_2O.',
    a: L(['+ H_2: <b>hydrogenation</b>', '+ X_2: <b>halogenation</b>', '+ HX: <b>hydrohalogenation</b>', '+ H_2O: <b>hydration</b>', '+ more CH_2=CH_2: addition polymerisation']), v: 'img:m7_addition' },
  { id: 'orx03', dp: '7.3.1', t: 'eq', q: 'Describe hydrogenation, with an equation and conditions.',
    a: E('CH_2=CH_2 + H_2 → CH_3CH_3') + L(['One H atom joins each carbon of the double bond, converting the alkene into an alkane.', 'Needs a metal catalyst: <b>Pt or Ni</b>.', 'Used to make margarine: liquid unsaturated fats become solid saturated fats.']) },
  { id: 'orx04', dp: '7.3.1', t: 'eq', q: 'Describe halogenation of an alkene, with an equation and conditions.',
    a: E('CH_2=CH_2 + Br_2 → CH_2BrCH_2Br') + L(['A diatomic halogen adds across the double bond to form a haloalkane (here 1,2-dibromoethane).', 'Halogens are strongly electrophilic, so <b>no catalyst or heat</b> is needed.']) },
  { id: 'orx05', dp: '7.3.1', t: 'prac', q: 'How does the bromine water test distinguish alkanes from alkenes?',
    a: L(['<b>Alkene</b> (or alkyne): bromine water <b>decolourises quickly</b> (addition reaction).', '<b>Alkane</b>: no change, stays brown; decolourises only slowly with UV light (substitution).']), v: 'img:m7_brwater' },
  { id: 'orx06', dp: '7.3.1', t: 'eq', q: 'Describe hydrohalogenation, with an example.',
    a: E('CH_2=CH_2 + HCl → CH_3CH_2Cl') + P('A hydrogen halide (HF, HCl, HBr, HI) adds across the double bond to form a haloalkane.') },
  { id: 'orx07', dp: '7.3.1', t: 'def', q: 'State Markovnikov’s rule and predict the products of propene + HBr.',
    a: P('When adding across a double or triple bond, the <b>hydrogen</b> attaches preferentially to the carbon that already has <b>the most hydrogens</b> (‘the rich get richer’). Used when the reagent can’t split into two identical parts.') + L(['Major product: <b>2-bromopropane</b>', 'Minor product: 1-bromopropane']), v: 'img:m7_markov' },
  { id: 'orx08', dp: '7.3.1', t: 'eq', q: 'Describe hydration of an alkene. What forms from propene?',
    a: E('CH_2=CH_2 + H_2O → CH_3CH_2OH') + L(['Water adds across the double bond to give an alcohol; dilute H_2SO_4 is used as the acid catalyst.', 'For asymmetric alkenes, Markovnikov’s rule applies: propene gives <b>propan-2-ol</b> (major) and propan-1-ol (minor).']) },
  { id: 'orx09', dp: '7.3.1', t: 'eq', q: 'How does an alkyne react with bromine?',
    a: E('CH≡CH + Br_2 → CHBr=CHBr') + E('CHBr=CHBr + Br_2 → CHBr_2CHBr_2') + P('Addition gives a dibromoalkene, then further addition can give a tetrabromoalkane.') },
  { id: 'orx10', dp: '7.3.2', t: 'def', q: 'What is a substitution reaction, and what conditions does an alkane need?',
    a: L(['An atom or functional group in a molecule is replaced by a different one.', 'Most common in alkanes; unsaturated molecules generally undergo addition instead.', 'Alkane + halogen needs <b>UV light</b> (or high temperature).']) + E('CH_4 + Cl_2 → CH_3Cl + HCl (UV light)') },
  { id: 'orx11', dp: '7.3.2', t: 'con', q: 'Outline the three-step mechanism of alkane substitution with chlorine.',
    a: OL(['UV light breaks Cl–Cl, forming two chlorine <b>radicals</b> (Cl•). A radical is an atom with an unpaired electron, not an ion: highly reactive.', 'A Cl• rips an H atom off the alkane, forming HCl and an alkyl radical.', 'A second Cl• combines with the alkyl radical, forming the haloalkane.']), v: 'img:m7_mechanism' },
  { id: 'orx12', dp: '7.3.2', t: 'con', q: 'Why does alkane substitution give a mixture of products? What should you assume in exams?',
    a: P('Given enough halogen and time, every hydrogen can be replaced, giving a mixture of haloalkanes (including position isomers for longer alkanes).') + N('In exams, assume a single substitution unless the question asks for more.') },
  { id: 'orx13', dp: '7.3.2', t: 'con', q: 'Compare how alkanes and alkenes react with halogens.',
    a: L(['<b>Alkene + X_2</b>: addition (halogenation); no catalyst or heat; one product.', '<b>Alkane + X_2</b>: substitution; needs UV light or high temperature; also produces HX.']) },
  { id: 'orx14', dp: '7.3.2', t: 'eq', q: 'Write equations for complete and incomplete combustion of propane.',
    a: E('C_3H_8(g) + 5O_2(g) → 3CO_2(g) + 4H_2O(g)') + P('Complete combustion.') + E('C_3H_8(g) + 4O_2(g) → CO_2(g) + 2CO(g) + 4H_2O(g)') + P('Limited oxygen.') + E('C_3H_8(g) + 3O_2(g) → 2CO(g) + C(s) + 4H_2O(g)') + P('Very limited oxygen.') + N('All combustions are exothermic and water is always a product. There’s no single correct incomplete equation unless mole ratios are given, but it must balance.') },
  { id: 'orx15', dp: '7.3.2', t: 'rec', q: 'What conventions do HSC examiners expect in combustion equations?',
    a: L(['Write the fuel in its state at 25 °C.', 'Write water as a gas, <b>unless</b> the equation shows the molar enthalpy of combustion; then water is liquid.', 'An improper fraction is allowed for the O_2 mole ratio.', 'A thermochemical equation shows ΔH (always negative) to the right:']) + E('C_5H_12(l) + 8O_2(g) → 5CO_2(g) + 6H_2O(l)   ΔH = −3535 kJ mol^{-1}') }
]});

M7_DECKS.push({ id: 'm7-al', fa: 'fa4', title: 'Alcohols: structure and properties', dps: ['7.4.1', '7.4.2'], cards: [
  { id: 'oal01', dp: '7.4.1', t: 'def', q: 'What is the functional group of an alcohol? How is it different from the hydroxide ion?',
    a: L(['The <b>hydroxyl group</b>, –OH, covalently bonded to carbon. It is uncharged.', 'The hydroxide ion, OH^-, is a charged polyatomic ion.', 'The O–H bond is polar (large electronegativity difference), which affects alcohols’ physical properties.']) },
  { id: 'oal02', dp: '7.4.1', t: 'def', q: 'Define primary, secondary and tertiary alcohols, with an example of each.',
    a: L(['<b>Primary (1°)</b>: the C bearing –OH is bonded to at most one R group, so –OH is terminal. E.g. butan-1-ol.', '<b>Secondary (2°)</b>: that C is bonded to two R groups. E.g. butan-2-ol.', '<b>Tertiary (3°)</b>: that C is bonded to three R groups. E.g. 2-methylpropan-2-ol.']) + N('R = an alkyl group.'), v: 'img:m7_alctypes' },
  { id: 'oal03', dp: '7.4.1', t: 'con', q: 'Classify as 1°, 2° or 3°: ethanol, propan-2-ol, 2-methylbutan-2-ol, pentan-3-ol.',
    a: L(['ethanol: <b>primary</b>', 'propan-2-ol: <b>secondary</b>', '2-methylbutan-2-ol: <b>tertiary</b>', 'pentan-3-ol: <b>secondary</b>']) },
  { id: 'oal04', dp: '7.4.2', t: 'con', q: 'Which intermolecular forces act between alcohol molecules, and which dominates?',
    a: L(['<b>Dispersion</b> forces, as in all molecules.', '<b>Dipole–dipole</b>: two polar bonds (C–O and O–H) and an asymmetrical shape give a permanent dipole.', '<b>Hydrogen bonding</b>: H is directly bonded to O.', 'Hydrogen bonding, the strongest, dominates their physical properties.']) },
  { id: 'oal05', dp: '7.4.2', t: 'con', q: 'How do the boiling points of alcohols change with chain length and number of –OH groups?',
    a: L(['Longer chain → larger molecule → stronger dispersion forces → higher melting and boiling points. (The melting point trend is less clear, because it depends on shape and crystal packing.)', 'More –OH groups → more hydrogen bonding → higher melting and boiling points.']) },
  { id: 'oal06', dp: '7.4.2', t: 'con', q: 'How do the boiling points of primary, secondary and tertiary alcohols compare?',
    a: L(['The more ‘exposed’ the –OH, the more it can hydrogen bond with other –OH groups.', 'So boiling point: <b>primary > secondary > tertiary</b> (differences are subtle).', 'Melting points can be anomalous: symmetrical 2-methylpropan-2-ol forms a very stable crystal lattice, so it has a high melting point.']) },
  { id: 'oal07', dp: '7.4.2', t: 'con', q: 'What decides an alcohol’s solubility in water? How many carbons can a water-soluble alcohol have?',
    a: L(['Solubility depends on solvent–solvent (water H-bonds), solute–solute (dispersion + H-bonds) and solute–solvent (H-bonds) interactions.', 'It depends on the proportions of the molecule that are polar and non-polar; a longer chain is more non-polar.', 'Alcohols up to <b>C3</b> are water-soluble (miscible); above that solubility drops rapidly, and they dissolve better in non-polar solvents like toluene or kerosene.']) + N('Miscible: solvent and solute combine completely in any proportion.') },
  { id: 'oal08', dp: '7.4.2', t: 'con', q: 'Compare the boiling points of pentane (72 g/mol), butan-1-amine (73 g/mol) and butan-1-ol (74 g/mol), and explain.',
    a: L(['Pentane 36 °C: dispersion forces only.', 'Butan-1-amine 78 °C: N–H bonds allow hydrogen bonding.', 'Butan-1-ol 118 °C: O is more electronegative than N, so O–H hydrogen bonds are stronger.']) }
]});

M7_DECKS.push({ id: 'm7-ar', fa: 'fa4', title: 'Reactions and production of alcohols', dps: ['7.4.4', '7.4.5', '7.4.7'], cards: [
  { id: 'oar01', dp: '7.4.4', t: 'eq', q: 'Why are alcohols good fuels? Write the equation for complete combustion of ethanol.',
    a: E('C_2H_5OH(l) + 3O_2(g) → 2CO_2(g) + 3H_2O(g)') + L(['High bond energy of C–C and C–H bonds makes them excellent fuels.', 'The oxygen atom in the alcohol helps combustion be more complete (‘cleaner’) than for alkanes, alkenes and alkynes.']) },
  { id: 'oar02', dp: '7.4.4', t: 'eq', q: 'Write the thermochemical equation for the combustion of butan-1-ol (ΔH_{c} = −2644 kJ mol^{-1}).',
    a: E('C_4H_9OH(l) + 6O_2(g) → 4CO_2(g) + 5H_2O(l)   ΔH = −2644 kJ mol^{-1}') + N('For a molar enthalpy of combustion, write water as a liquid (its state at 25 °C).') },
  { id: 'oar03', dp: '7.4.4', t: 'def', q: 'How do you calculate the molar enthalpy of combustion from calorimetry data?',
    a: E('q = mcΔT') + L(['q = heat released (J); m = mass of <b>water</b> (kg); c = 4.18 × 10^{3} J kg^{-1} K^{-1}; ΔT = temperature change of the water (K)']) + E('ΔH_{c} = ' + F('−q', 'n')) + L(['n = moles of fuel burned (from the mass lost by the burner)', 'ΔH_{c} is always negative: combustion is exothermic', 'Standard conditions: 25 °C and 100 kPa']) },
  { id: 'oar04', dp: '7.4.4', t: 'calc', q: 'A methanol burner went from 80.55 g to 80.03 g, heating 20.00 g of water from 19.5 °C to 56.3 °C. Calculate ΔH_{c} of methanol.',
    a: L(['m(CH_3OH) burned = 80.55 − 80.03 = 0.52 g; n = 0.52 ÷ 32.04 = 0.0162 mol', 'q = 0.02000 × 4.18 × 10^{3} × 36.8 = 3076 J = 3.076 kJ', 'ΔH_{c} = −3.076 ÷ 0.0162 = <b>−190 kJ mol^{-1}</b> (slide: −189.570)']) + N('The theoretical value is −727 kJ mol^{-1}: see the next card for why it’s so different.') },
  { id: 'oar05', dp: '7.4.4', t: 'con', q: 'What does calorimetry assume, and how can a spirit burner experiment be made more valid?',
    a: P('Assumes complete combustion, and that all the energy released goes into the water.') + L(['Maximise oxygen: trim wicks; keep a suitable distance between flame and calorimeter.', 'Minimise heat loss: lid on the calorimeter; draught shield; insulate the sides; keep the base clean (soot insulates) and dry.', 'A bomb calorimeter (sample in oxygen, electrical ignition, water jacket) addresses all of these.']) },
  { id: 'oar06', dp: '7.4.4', t: 'con', q: 'Why are experimental enthalpies of combustion lower than theoretical values?',
    a: L(['Heat lost to the surroundings rather than the water', 'Incomplete combustion from limited oxygen or a poor burner set-up', 'Alcohol not fully vaporised before burning', 'Impurities in the fuel', 'Evaporation of alcohol before ignition']) },
  { id: 'oar07', dp: '7.4.4', t: 'eq', q: 'Describe the dehydration of an alcohol, with an equation and conditions.',
    a: E('CH_3CH_2OH → CH_2=CH_2 + H_2O   (conc. H_2SO_4, heat ~180 °C)') + L(['An <b>elimination</b> reaction (the reverse of addition, and of hydration).', '–OH is removed from one carbon and an H from the <b>adjacent</b> carbon, forming an alkene and water.', 'Conc. sulfuric acid is the catalyst and dehydrating agent.', 'No H on a neighbouring carbon → no dehydration (e.g. 2,2-dimethylpropan-1-ol).']) },
  { id: 'oar08', dp: '7.4.4', t: 'con', q: 'Which alcohols dehydrate most easily? State Zaitsev’s rule and apply it to 2-methylbutan-2-ol.',
    a: L(['Reactivity: <b>tertiary > secondary > primary</b>.', '<b>Zaitsev’s rule</b>: the major product has the double bond carrying the <b>fewest hydrogens</b> (H is removed from the ‘poorer’ carbon).', '2-methylbutan-2-ol → <b>2-methylbut-2-ene</b> (major) and 2-methylbut-1-ene (minor).']), v: 'img:m7_dehyd' },
  { id: 'oar09', dp: '7.4.4', t: 'eq', q: 'Describe the substitution of an alcohol with a hydrogen halide.',
    a: E('CH_3CH_2OH + HBr → CH_3CH_2Br + H_2O') + L(['Alcohol + HX → haloalkane + water.', 'Catalysed by conc. <b>H_2SO_4</b>, not HCl or HBr, since hydrogen halides would act as reactants.', 'Heat may be needed, especially for 1° alcohols.', 'Alcohol reactivity 3° > 2° > 1°; halide reactivity HI > HBr > HCl (HF is generally unreactive).']) },
  { id: 'oar10', dp: '7.4.4', t: 'def', q: 'What does ‘oxidation’ mean in organic chemistry, and how is it written in equations?',
    a: L(['A carbon gains a bond to oxygen and/or loses a bond to hydrogen.', 'Needs an oxidant such as permanganate (MnO_4^-) or dichromate (Cr_2O_7^{2-}) in acidic conditions.', 'The oxidant goes over the arrow, or as [O]; acid is shown as H^+; the reduced oxidant is rarely shown.']) },
  { id: 'oar11', dp: '7.4.4', t: 'eq', q: 'What does a primary alcohol form with a strong oxidant, and with a weak one?',
    a: E('CH_3CH_2OH → CH_3CHO → CH_3COOH   ([O]/H^+ each step)') + L(['<b>Strong</b> oxidant (acidified K_2Cr_2O_7 or KMnO_4): via the <b>aldehyde</b> to the <b>carboxylic acid</b>.', '<b>Weak</b> oxidant (acidified CrO_3): only to the aldehyde.']) },
  { id: 'oar12', dp: '7.4.4', t: 'eq', q: 'What happens when secondary and tertiary alcohols are oxidised?',
    a: E('CH_3CH(OH)CH_3 → CH_3COCH_3   ([O]/H^+)') + L(['<b>Secondary</b> → <b>ketone</b> (–OH isn’t terminal). Strong or weak oxidants both work; propan-2-ol gives propanone.', '<b>Tertiary</b>: cannot be oxidised. The carbon carrying –OH has no hydrogen to lose.']) },
  { id: 'oar13', dp: '7.4.4', t: 'con', q: 'Use oxidation states to show that ethanol → ethanoic acid is an oxidation.',
    a: L(['Rules: H = +1, O = −2; the sum for a neutral molecule is 0.', 'The carbon bonded to –OH goes from −1 in ethanol to +3 in ethanoic acid: its oxidation state increases, so it’s oxidised (loss of electrons).', 'The permanganate or dichromate is reduced at the same time; those half-equations are on the HSC data sheet.']) },
  { id: 'oar14', dp: '7.4.4', t: 'prac', q: 'What colour changes show oxidation with permanganate and dichromate?',
    a: L(['<b>Acidified permanganate</b>: purple → colourless (Mn^{2+}) in acid, or a brown MnO_2 precipitate in neutral/alkaline conditions.', '<b>Acidified dichromate</b>: orange → green.', 'For the HSC, any colour change is a positive test for oxidation.']) },
  { id: 'oar15', dp: '7.4.5', t: 'rec', q: 'What are the three ways of producing alcohols?',
    a: L(['<b>Hydration of alkenes</b>: industrially, ethene (from crude oil or natural gas) + water → ethanol', '<b>Substitution of haloalkanes</b> with water or hydroxide', '<b>Fermentation</b> of sugars']), v: 'img:m7_pathways' },
  { id: 'oar16', dp: '7.4.5', t: 'eq', q: 'How is an alcohol made from a haloalkane? Give conditions.',
    a: E('CH_3CH_2Br + OH^- → CH_3CH_2OH + Br^-') + L(['The C–X bond is very polar, so carbon is δ+ and attracts nucleophiles: <b>nucleophilic substitution</b>.', 'With water (<b>hydrolysis</b>): slow even when heated; needs a catalyst.', 'With hydroxide (NaOH/KOH over the arrow): faster, no catalyst. The base must be <b>dilute and at room temperature</b>, otherwise elimination gives an alkene.']) },
  { id: 'oar17', dp: '7.4.5', t: 'con', q: 'Where do the haloalkanes for alcohol production come from?',
    a: L(['Addition of X_2 or HX to alkenes: no catalyst needed.', 'Substitution of alkanes with X_2: heat or UV light needed.', 'Making a haloalkane is a common step in organic synthesis pathways.']) },
  { id: 'oar18', dp: '7.4.5', t: 'def', q: 'What is fermentation?',
    a: P('A metabolic process in which microorganisms such as yeast and bacteria convert carbohydrates into alcohol, e.g. glucose → ethanol, with yeast shown over the arrow.') + N('Researched further in Task 3.') },
  { id: 'oar19', dp: '7.4.7', t: 'def', q: 'How do organic (fossil) fuels differ from biofuels?',
    a: P('Organic fuels here means <b>fossil fuels</b>; <b>biofuels</b> come from recently living material (e.g. ethanol from fermentation).') + N('Comparing them is part of the Task 3 research.') }
]});

M7_DECKS.push({ id: 'm7-ab', fa: 'fa5', title: 'Organic acids, bases and functional group properties', dps: ['7.5.1'], cards: [
  { id: 'oab01', dp: '7.5.1', t: 'eq', q: 'Show that carboxylic acids are Brønsted–Lowry acids, using ethanoic acid.',
    a: E('CH_3COOH(aq) + H_2O(l) ⇌ CH_3COO^-(aq) + H_3O^+(aq)') + P('It donates a proton. Most molecules don’t ionise, so it’s a <b>weak</b> acid.') },
  { id: 'oab02', dp: '7.5.1', t: 'eq', q: 'Write equations for ethanoic acid reacting with NaOH, Na_2CO_3 and Mg.',
    a: E('CH_3COOH + NaOH → CH_3COONa + H_2O') + E('2CH_3COOH + Na_2CO_3 → 2CH_3COONa + CO_2 + H_2O') + E('2CH_3COOH(aq) + Mg(s) → (CH_3COO)_2Mg(aq) + H_2(g)') + P('Acid + base, acid + carbonate, acid + metal.') },
  { id: 'oab03', dp: '7.5.1', t: 'eq', q: 'Show that amines are bases, using methylamine.',
    a: E('CH_3NH_2(aq) + H_2O(l) ⇌ CH_3NH_3^+(aq) + OH^-(aq)') + P('Water donates H^+ to the amine, forming a methylammonium ion and hydroxide. Most molecules don’t ionise: a <b>weak</b> base.') },
  { id: 'oab04', dp: '7.5.1', t: 'con', q: 'What makes an organic compound amphoteric? Give an example.',
    a: L(['Any molecule with a hydrogen atom can donate a proton (acid); any with a lone pair can accept one (base).', '<b>Alcohols</b> have both acidic and basic sites; which way they act depends on the other reagent.']) },
  { id: 'oab05', dp: '7.5.1', t: 'con', q: 'Compare the boiling points and water solubility of aldehydes and ketones with alkanes and alcohols.',
    a: L(['The polar C=O gives <b>dipole–dipole</b> forces: higher melting and boiling points than similar alkanes.', 'They can’t hydrogen bond with each other: lower than similar alcohols.', 'They’re water-soluble: water’s δ+ H bonds to the lone pairs on the carbonyl O. Solubility falls as the chain gets longer.']) },
  { id: 'oab06', dp: '7.5.1', t: 'con', q: 'Why do carboxylic acids have very high boiling points? How does their solubility change?',
    a: L(['The carboxyl group (C=O + O–H on one carbon) is very polar and hydrogen bonds.', 'Two molecules form two H-bonds to make a stable <b>dimer</b> with double the mass, so stronger dispersion forces too.', 'Short chains are very water-soluble; solubility falls as chain length grows. The reverse happens in non-polar solvents.']) },
  { id: 'oab07', dp: '7.5.1', t: 'def', q: 'What are primary, secondary and tertiary amines and amides?',
    a: L(['Amines are like NH_3 with H atoms replaced by carbon chains: 1° N bonded to one carbon, 2° to two, 3° to three.', 'Amides have the N bonded to a carbonyl carbon (–CONR′R″); they can also be 1°, 2° or 3°.', '1° and 2° amines and amides have N–H bonds, so hydrogen bonding dominates for short chains.']) },
  { id: 'oab08', dp: '7.5.1', t: 'con', q: 'Rank pentane, butan-1-amine, butan-1-ol, propanoic acid and propanamide (all ≈ 73 g/mol) by boiling point.',
    a: L(['Pentane 36 °C', 'Butan-1-amine 78 °C', 'Butan-1-ol 118 °C', 'Propanoic acid 141 °C', '<b>Propanamide 213 °C</b>']) + N('Amides form complex hydrogen-bonded structures; their boiling points are uniformly high (ethanamide 221 °C). Proteins are natural polyamides.') },
  { id: 'oab09', dp: '7.5.1', t: 'con', q: 'Misconception check: do carboxylic acids have the highest boiling points? Explain.',
    a: P('No: primary and secondary amides are generally higher. E.g. ethanoic acid 118 °C; ethanamide 221 °C; N-methylethanamide 205 °C; N,N-dimethylethanamide 165 °C.') + L(['Primary amides have two N–H bonds, so form more hydrogen bonds.', 'Amides have resonance structures, putting ionic charges on O and N that greatly increase attraction.', 'Tertiary amides have no N–H, so no H-bonding; their boiling points are close to carboxylic acids’.']), v: 'img:m7_amidebp' },
  { id: 'oab10', dp: '7.5.1', t: 'eq', q: 'How are amides formed?',
    a: P('A <b>condensation</b> reaction between a carboxylic acid and ammonia or an amine, at high temperature.') + L(['Carboxylic acid + ammonia → primary amide', 'Carboxylic acid + primary amine → secondary amide', 'Carboxylic acid + secondary amine → tertiary amide']) }
]});

M7_DECKS.push({ id: 'm7-es', fa: 'fa5', title: 'Esters, lab tests and synthesis pathways', dps: ['7.5.1', '7.5.3', '7.5.5', '7.5.6', '7.6'], cards: [
  { id: 'oes01', dp: '7.5.3', t: 'def', q: 'How is an ester named from the alcohol and acid that made it? Name the ester from methanol and propanoic acid.',
    a: L(['The ‘alkyl’ part (substituent) comes from the <b>alcohol</b>.', 'The ‘alkanoate’ part (parent chain) comes from the <b>carboxylic acid</b>.', 'Methanol + propanoic acid → <b>methyl propanoate</b>.', 'Esters of acetic acid are often called acetates, e.g. ethyl acetate.', 'Esters often have fruity or floral aromas and flavours.']) },
  { id: 'oes02', dp: '7.5.3', t: 'eq', q: 'Write the equation for making ethyl ethanoate, with conditions.',
    a: E('CH_3COOH + CH_3CH_2OH ⇌ CH_3COOCH_2CH_3 + H_2O') + L(['Esterification: carboxylic acid + alcohol ⇌ ester + water.', 'A reversible <b>condensation</b> reaction, catalysed by conc. H_2SO_4.']) },
  { id: 'oes03', dp: '7.5.3', t: 'con', q: 'Why do esters have lower boiling points and lower water solubility than carboxylic acids or alcohols of similar mass?',
    a: L(['Esters are polar (C–O and C=O bonds, asymmetrical shape), so have dipole–dipole forces…', '…but no hydrogen bonding between their molecules.', 'So: much lower boiling points, much less water-soluble, and volatile, which explains their strong aromas.']) },
  { id: 'oes04', dp: '7.5.3', t: 'prac', q: 'How is the yield of an esterification improved in the lab?',
    a: L(['<b>Reflux</b>: heat with a cooling condenser attached, so volatile reactants and products aren’t lost while running hotter. Use a heating mantle (no naked flame).', '<b>Conc. H_2SO_4</b>: catalyst that also absorbs water, increasing ester yield.', '<b>Excess alcohol</b>: drives more ester formation; preferred over excess acid because it also acts as a solvent for the acid.']) + N('Esterifications aren’t reliably exo- or endothermic; the enthalpy difference is small.') },
  { id: 'oes05', dp: '7.5.3', t: 'prac', q: 'After refluxing, how is the ester separated and purified?',
    a: OL(['Let the mixture cool.', 'Add it to sodium carbonate solution (‘washing’) to react away the H_2SO_4 and leftover carboxylic acid.', 'Two layers form: the ester, and everything else (the alcohol is water-soluble).', 'Separate with a separating funnel, or distil for a more precise separation.']) },
  { id: 'oes06', dp: '7.5.1', t: 'prac', q: 'Prac 7.4: Summarise the results of the chemical tests on each homologous series.', a: '', v: 'm7tests' },
  { id: 'oes07', dp: '7.5.1', t: 'con', q: 'How can you tell primary, secondary and tertiary alcohols apart using chemical tests?',
    a: OL(['Add an oxidant such as acidified KMnO_4: tertiary shows no change; primary and secondary change colour.', 'Then add Lucas’ reagent (ZnCl_2/HCl): primary shows no change; secondary turns cloudy after a few minutes or with heating; tertiary forms a white precipitate immediately.']) },
  { id: 'oes08', dp: '7.5.1', t: 'eq', q: 'How does Lucas’ reagent work? Write the equation for a tertiary alcohol.',
    a: E('(CH_3)_3COH + HCl → (CH_3)_3CCl + H_2O   (ZnCl_2 catalyst)') + L(['Conc. HCl + ZnCl_2 catalyst. The –OH is substituted by Cl (nucleophilic substitution).', 'The chloroalkane is non-polar and insoluble in the aqueous reagent, so it appears as a <b>white precipitate</b> (cloudiness).', 'Tertiary: fast; secondary: slow; primary: slow or not at all (its carbocation is unstable and hard to form).']) },
  { id: 'oes09', dp: '7.5.1', t: 'con', q: 'Why is Benedict’s solution a better test for aldehydes than permanganate?',
    a: L(['Permanganate is a strong, non-specific oxidant: it also oxidises 1° and 2° alcohols, alkenes and alkynes.', 'Benedict’s (Cu^{2+} in alkaline solution) is mild and selective: it oxidises aldehydes (and reducing sugars) but not most alcohols or ketones.', 'Positive test: aldehyde → carboxylate; Cu^{2+} is reduced to a <b>red-orange Cu_2O precipitate</b> (needs hot water).']) },
  { id: 'oes10', dp: '7.5.1', t: 'prac', q: 'Prac 7.5: How did carboxylic acids, alcohols and amines respond to litmus, sodium carbonate and metals?',
    a: L(['<b>Litmus</b>: carboxylic acids turn blue litmus red; amines turn red litmus blue; alcohols cause no change.', '<b>Na_2CO_3</b>: carboxylic acids fizz (CO_2): 2CH_3COOH + Na_2CO_3 → 2CH_3COONa + CO_2 + H_2O. Alcohols and amines give no gas.', '<b>Metals</b>: acids give H_2 faster than alcohols (acids donate protons more readily); alcohols form an alkoxide + H_2. Sodium reacts faster than magnesium.']) },
  { id: 'oes11', dp: '7.5.1', t: 'prac', q: 'How does silver nitrate distinguish haloalkanes?',
    a: P('Nucleophilic substitution: the halide leaves and is replaced by –OH (or ethoxy) from the solvent; Ag^+ precipitates the halide.') + L(['Chloroalkane: white AgCl, slowly (~30 min)', 'Bromoalkane: cream AgBr (~3 min)', 'Iodoalkane: thick pale-yellow AgI, immediately', 'Fluoroalkane: no precipitate (strong C–F bond; AgF is soluble anyway)']) },
  { id: 'oes12', dp: '7.5.1', t: 'prac', q: 'Why is propanone used to rinse test tubes, and why is a pop test unsafe in Prac 7.5?',
    a: L(['Propanone has polar and non-polar regions, so it dissolves water and organic residues; its low boiling point means it evaporates quickly, leaving tubes dry.', 'The metal reactions produce flammable hydrogen, and organic vapours could ignite, so a naked flame is dangerous.']) },
  { id: 'oes13', dp: '7.5.5', t: 'def', q: 'What are surfactants and how do they help cleaning?',
    a: P('Surface-active agents, including soaps and detergents. They remove dirt and grease by helping these non-polar substances associate with water, so they wash away.') + N('Structure and action are researched in Task 3.') },
  { id: 'oes14', dp: '7.5.6', t: 'def', q: 'What should an organic synthesis flowchart show, and what can it leave out?',
    a: L(['Reagents and conditions summarised around each arrow (reagent = reactants <b>and</b> catalysts).', 'It needn’t be balanced or show by-products, and doesn’t follow standard flowchart shapes.', 'Working backwards from the product (<b>retrosynthesis</b>) helps; a sound grasp of Markovnikov’s rule is valuable.']), v: 'img:m7_pathways' },
  { id: 'oes15', dp: '7.5.6', t: 'con', q: 'Plan a synthesis of ethanoic acid from ethene.',
    a: E('ethene → ethanol → ethanal → ethanoic acid') + L(['Step 1: + H_2O, dilute H_2SO_4 (hydration)', 'Steps 2 and 3: [O]/H^+, e.g. acidified KMnO_4 (oxidation of a primary alcohol, via the aldehyde)']) + N('Retrosynthesis: a carboxylic acid comes from oxidising a primary alcohol, which comes from hydrating an alkene.') },
  { id: 'oes16', dp: '7.5.6', t: 'exam', q: 'This flowchart starts from but-1-ene. Name the products of Steps 1, 4, 5 and 6.', vf: 'img:m7_flow_q',
    a: L(['Step 1 (+ HCl): <b>2-chlorobutane</b>, by Markovnikov’s rule', 'Step 2 (H_2, metal catalyst) gives butane; Step 3 (Cl_2, UV) gives 1-chlorobutane + HCl', 'Step 4 (NaOH(aq)): <b>butan-1-ol</b>', 'Step 5 (excess KMnO_4/H_2SO_4): <b>butanoic acid</b>', 'Step 6 (butan-1-ol + butanoic acid, conc. H_2SO_4): <b>butyl butanoate</b>']) },
  { id: 'oes17', dp: '7.5.6', t: 'exam', q: 'Using this diagram, give the letter(s) of a substitution, oxidation, fermentation, esterification, polymerisation, hydrolysis, addition and acid–base reaction.', vf: 'img:m7_conv_q',
    a: L(['Substitution: <b>A</b>', 'Oxidation: <b>C, E</b>', 'Fermentation: <b>F</b>', 'Esterification: <b>I</b>', 'Polymerisation: <b>H</b>', 'Hydrolysis: <b>J</b>', 'Addition: <b>B</b>', 'Acid–base: <b>D</b>']) + N('Also from this diagram: A gives 2-chlorobutane; E uses H^+/KMnO_4 via ethanal; D uses sodium hydroxide; I uses conc. H_2SO_4.') },
  { id: 'oes18', dp: '7.6', t: 'def', q: 'What is a polymer? Give an example made from ethylene.',
    a: P('A macromolecule (very large molecule) made of many <b>monomer</b> molecules joined by covalent bonds. E.g. addition polymerisation of ethylene gives polyethylene, n(–CH_2–CH_2–).') + N('Structure, properties and uses are researched in Task 3.') }
]});

